import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const group = new Group();
  const container = new Group();
  group.add(container);

  const timelines = [];

  // Palette from spec
  const colors = config.intent?.visualSpec?.colors ?? {};
  const inkStr = colors.ink ?? '#16161d';
  const paperStr = colors.paper ?? '#e8ecf2';
  const accentStr = colors.accent ?? '#ff2a38';
  const surfaceStr = colors.surface ?? '#0b0b10';

  const inkCol = new Color(inkStr);
  const accentCol = new Color(accentStr);
  const surfaceCol = new Color(surfaceStr);

  // Text content items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // --- Backdrop: engineered gradient (surface -> ink, vertical) ---
  const backdropGeo = new PlaneGeometry(7, 2.4);
  const backdropMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0,
  });

  backdropMat.colorNode = mix(
    vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b),
    vec3(inkCol.r, inkCol.g, inkCol.b),
    smoothstep(0.0, 1.0, uv().y)
  );

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.5);
  container.add(backdrop);

  // --- Image plane (subtle background texture) ---
  let imgMesh = null;
  if (config.imageUrl) {
    const imgGeo = new PlaneGeometry(5, 2.4);
    const imgMat = new MeshBasicNodeMaterial({
      transparent: true,
      opacity: 0,
    });
    imgMesh = new Mesh(imgGeo, imgMat);
    imgMesh.position.set(0, 0, -0.35);
    container.add(imgMesh);

    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // --- Accent bar ---
  const accentGeo = new PlaneGeometry(0.55, 0.025);
  const accentMat = new MeshBasicNodeMaterial({
    color: accentCol,
    transparent: true,
  });
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -0.52, 0.02);
  accentBar.scale.x = 0;
  container.add(accentBar);

  // --- Headline text ---
  for (const item of items) {
    const textStr = typeof item === 'string' ? item : (item.text || '');
    if (!textStr) continue;
    const fontSize = item.typography?.fontSize || 96;
    const headline = ctx.fontAtlas.createText(textStr, {
      fontSize: fontSize,
      color: paperStr,
      align: 'center',
    });
    headline.position.set(0, 0, 0.1);
    container.add(headline);
  }

  // --- Entrance animation: rise-in + fade-up ---
  const tl = gsap.timeline();
  timelines.push(tl);

  container.position.y = 0.3;

  tl.to(container.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);

  tl.to(backdropMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);

  if (imgMesh) {
    tl.to(imgMesh.material, {
      opacity: 0.1,
      duration: 0.6,
      ease: 'power2.out',
    }, 0.15);
  }

  tl.to(accentBar.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power3.out',
  }, 0.35);

  // No interactivity per spec
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        mats.forEach(m => {
          if (m.map) m.map.dispose();
          m.dispose();
        });
      }
    });
  };

  return group;
}
